const body = $json.body || $json;
const p = body.payload || {};
const contact_id = p.contact_id || body.contact_id || null;
const email = p.email || body.email || null;

if (!contact_id && !email) {
  throw new Error('Either contact_id or email is required');
}

// Build the batch read request
// If we have contact_id, use 'hs_object_id' as idProperty
// If we only have email, use 'email' as idProperty
const idProperty = contact_id ? 'hs_object_id' : 'email';
const idValue = contact_id || email;

return [{
  json: {
    idProperty,
    idValue,
    email,
    contact_id,
    session_id: body.session_id || null
  }
}];

const lookup = $('Code -- build lookup request').item.json;
const response = $json;

// Handle not-found or error responses
if (response.status === 207 || response.errors?.length > 0 || !response.results?.length) {
  return [{
    json: {
      status: 'not_found',
      action_id: 'acq.contact.get',
      email: lookup.email,
      contact_id: lookup.contact_id,
      session_id: lookup.session_id
    }
  }];
}

const contact = response.results[0];
const props = contact.properties || {};

return [{
  json: {
    status: 'executed',
    action_id: 'acq.contact.get',
    contact_id: contact.id,
    email: props.email || lookup.email,
    first_name: props.firstname || null,
    last_name: props.lastname || null,
    phone: props.phone || null,
    company: props.company || null,
    pain_points: props.cx_pain_points || null,
    pci: props.cx_pci ? Number(props.cx_pci) : null,
    lifecycle_stage: props.lifecyclestage || null,
    lead_status: props.hs_lead_status || null,
    session_id: lookup.session_id
  }
}];
